"""Sets the IFC Description attribute of the first wall with SetIFCAttributesOfElements, reads it back and restores it.

Needs at least one Wall. Available only in Archicad 25, 26 and 27.
"""
import aclib

walls = aclib.RunTapirCommand ('GetElementsByType', {'elementType': 'Wall'})['elements'][:1]
if not walls:
    raise SystemExit ('No wall in the project.')
elementId = walls[0]['elementId']

def GetDescription ():
    response = aclib.RunTapirCommand ('GetIFCAttributesOfElements', {'elements': [{'elementId': elementId}]})
    attributes = response['elementIFCAttributes'][0].get ('ifcAttributes', [])
    return next ((attribute.get ('value', '') for attribute in attributes if attribute['name'] == 'Description'), None)

originalDescription = GetDescription ()
if originalDescription is None:
    raise SystemExit ('The wall has no IFC Description attribute.')

aclib.PrintJson (aclib.RunTapirCommand ('SetIFCAttributesOfElements', {
    'elementIFCAttributeValues': [{'elementId': elementId, 'name': 'Description', 'value': 'Set by Tapir'}]
}))
print ('Description:', GetDescription ())

aclib.RunTapirCommand ('SetIFCAttributesOfElements', {
    'elementIFCAttributeValues': [{'elementId': elementId, 'name': 'Description', 'value': originalDescription}]
})

"""Sets a local IFC property of the first wall with SetIFCPropertiesOfElements and reads it back.

Needs at least one Wall. The property 'Tapir_Example / Note' is removed again at the end.
Available only in Archicad 25, 26 and 27.
"""
import aclib

walls = aclib.RunTapirCommand ('GetElementsByType', {'elementType': 'Wall'})['elements'][:1]
if not walls:
    raise SystemExit ('No wall in the project.')
elementId = walls[0]['elementId']

aclib.PrintJson (aclib.RunTapirCommand ('SetIFCPropertiesOfElements', {
    'elementIFCPropertyValues': [{
        'elementId': elementId,
        'propertySetName': 'Tapir_Example',
        'propertyName': 'Note',
        'type': 'IfcLabel',
        'value': 'Set by Tapir'
    }]
}))

response = aclib.RunTapirCommand ('GetIFCPropertiesOfElements', {'elements': [{'elementId': elementId}]})
for ifcProperty in response['elementIFCProperties'][0].get ('ifcProperties', []):
    if ifcProperty['propertySetName'] == 'Tapir_Example':
        print (ifcProperty['name'], '=', ifcProperty['value'])

aclib.RunTapirCommand ('RemoveIFCPropertiesOfElements', {
    'elementIFCProperties': [{'elementId': elementId, 'propertySetName': 'Tapir_Example', 'propertyName': 'Note'}]
})

"""Stores an IFC classification reference on the first wall with SetIFCClassificationReferencesOfElements and reads it back.

Needs at least one Wall. The reference is removed again at the end. Available only in Archicad 25, 26 and 27.
"""
import aclib

walls = aclib.RunTapirCommand ('GetElementsByType', {'elementType': 'Wall'})['elements'][:1]
if not walls:
    raise SystemExit ('No wall in the project.')
elementId = walls[0]['elementId']

aclib.PrintJson (aclib.RunTapirCommand ('SetIFCClassificationReferencesOfElements', {
    'elementIFCClassificationReferences': [{
        'elementId': elementId,
        'identification': 'TE-01',
        'name': 'Tapir Example Item',
        'location': 'https://example.com/classification/TE-01',
        'referencedSource': {
            'name': 'Tapir Example Classification',
            'edition': '1.0',
            'editionDate': '2026-01-01',
            'description': 'A classification made up for this example.',
            'location': 'https://example.com/classification'
        }
    }]
}))

aclib.RunTapirCommand ('GetIFCClassificationReferencesOfElements', {
    'elements': [{'elementId': elementId}],
    'storedOnly': True
})

aclib.RunTapirCommand ('RemoveIFCClassificationReferencesOfElements', {
    'elementIFCClassificationReferences': [{'elementId': elementId, 'referencedSource': {'name': 'Tapir Example Classification'}}]
})

